import { useEffect, useState, useCallback } from "react";
import { supabase } from "@/integrations/supabase/client";
import { Shield, Eye, FilePlus, Download, Key, LogIn, Trash2, RefreshCw, Search } from "lucide-react";
import { Input } from "@/components/ui/input";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Button } from "@/components/ui/button";

interface AuditEntry {
  id: string;
  actor_email: string;
  action: string;
  resource: string;
  resource_id: string | null;
  detail: Record<string, any>;
  ip_address: string | null;
  ts: string;
}

const ACTION_META: Record<string, { label: string; icon: React.ElementType; color: string }> = {
  view_threat:     { label: "Viewed Threat",    icon: Eye,      color: "text-slate-400" },
  create_case:     { label: "Created Case",     icon: FilePlus, color: "text-cyan-400" },
  generate_report: { label: "Generated Report", icon: Download, color: "text-indigo-400" },
  export_data:     { label: "Exported Data",    icon: Download, color: "text-amber-400" },
  login:           { label: "Login",            icon: LogIn,    color: "text-emerald-400" },
  api_call:        { label: "API Call",         icon: Key,      color: "text-violet-400" },
  delete_item:     { label: "Deleted Item",     icon: Trash2,   color: "text-red-400" },
  create_alert:    { label: "Created Alert",    icon: Shield,   color: "text-orange-400" },
};

function timeAgo(iso: string) {
  const m = Math.floor((Date.now() - new Date(iso).getTime()) / 60000);
  if (m < 1) return "just now";
  if (m < 60) return `${m}m ago`;
  if (m < 1440) return `${Math.floor(m / 60)}h ago`;
  return `${Math.floor(m / 1440)}d ago`;
}

// Hook to write audit entries (call from anywhere in the app)
export function useAudit() {
  return {
    log: async (action: string, resource: string, resourceId?: string, detail?: Record<string, any>) => {
      try {
        const { data: { session } } = await supabase.auth.getSession();
        const actor_email = session?.user?.email ?? "anonymous";
        await supabase.from("audit_logs").insert([{
          actor_email,
          action,
          resource,
          resource_id: resourceId ?? null,
          detail: detail ?? {},
        }]);
      } catch { /* non-blocking */ }
    },
  };
}

export function AuditLogViewer() {
  const [entries, setEntries] = useState<AuditEntry[]>([]);
  const [loading, setLoading] = useState(true);
  const [search, setSearch] = useState("");
  const [actionFilter, setActionFilter] = useState("all");
  const [page, setPage] = useState(0);
  const PAGE_SIZE = 50;

  const load = useCallback(async () => {
    setLoading(true);
    let q = supabase.from("audit_logs")
      .select("id,actor_email,action,resource,resource_id,detail,ip_address,ts")
      .order("ts", { ascending: false })
      .range(page * PAGE_SIZE, (page + 1) * PAGE_SIZE - 1);
    if (actionFilter !== "all") q = q.eq("action", actionFilter);
    if (search.trim()) q = q.ilike("actor_email", `%${search.trim()}%`);
    const { data } = await q;
    setEntries((data ?? []) as AuditEntry[]);
    setLoading(false);
  }, [search, actionFilter, page]);

  useEffect(() => { load(); }, [load]);

  return (
    <div className="space-y-4">
      {/* Filters */}
      <div className="flex flex-wrap gap-2">
        <div className="relative flex-1 min-w-[160px]">
          <Search className="absolute left-2.5 top-1/2 -translate-y-1/2 h-3.5 w-3.5 text-slate-500" />
          <Input
            className="pl-8 h-8 text-xs"
            placeholder="Filter by user…"
            value={search}
            onChange={e => { setSearch(e.target.value); setPage(0); }}
          />
        </div>
        <Select value={actionFilter} onValueChange={v => { setActionFilter(v); setPage(0); }}>
          <SelectTrigger className="h-8 text-xs w-44"><SelectValue placeholder="All actions" /></SelectTrigger>
          <SelectContent>
            <SelectItem value="all" className="text-xs">All actions</SelectItem>
            {Object.entries(ACTION_META).map(([k, v]) => (
              <SelectItem key={k} value={k} className="text-xs">{v.label}</SelectItem>
            ))}
          </SelectContent>
        </Select>
        <Button variant="outline" size="sm" className="h-8 gap-1.5 text-xs" onClick={() => load()}>
          <RefreshCw className="h-3 w-3" /> Refresh
        </Button>
      </div>

      {/* Table */}
      <div className="rounded-xl overflow-hidden" style={{ border: "1px solid rgba(6,182,212,0.1)" }}>
        <div className="grid grid-cols-[auto_1fr_1fr_1fr_auto] gap-0 text-[10px] font-semibold uppercase tracking-wider text-slate-500 px-4 py-2"
          style={{ background: "rgba(6,182,212,0.04)", borderBottom: "1px solid rgba(6,182,212,0.08)" }}>
          <span className="w-28 pr-4">Time</span>
          <span>User</span>
          <span>Action</span>
          <span>Resource</span>
          <span className="w-24 text-right">IP</span>
        </div>

        {loading ? (
          <div className="py-8 text-center text-sm text-slate-500">Loading audit log…</div>
        ) : entries.length === 0 ? (
          <div className="py-10 text-center text-sm text-slate-600">
            No audit entries yet. Actions like viewing threats, creating cases, and generating reports will appear here.
          </div>
        ) : (
          <div className="divide-y" style={{ borderColor: "rgba(255,255,255,0.04)" }}>
            {entries.map(e => {
              const meta = ACTION_META[e.action] ?? { label: e.action, icon: Shield, color: "text-slate-500" };
              const Icon = meta.icon;
              return (
                <div key={e.id} className="grid grid-cols-[auto_1fr_1fr_1fr_auto] gap-0 px-4 py-2.5 hover:bg-white/[0.02] transition-colors items-center">
                  <div className="w-28 pr-4 text-[10px] text-slate-600 shrink-0">{timeAgo(e.ts)}</div>
                  <div className="text-xs text-slate-300 truncate pr-3">{e.actor_email}</div>
                  <div className={`flex items-center gap-1.5 text-xs ${meta.color}`}>
                    <Icon className="h-3 w-3 shrink-0" />
                    <span>{meta.label}</span>
                  </div>
                  <div className="text-xs text-slate-500 truncate pr-3">
                    {e.resource}
                    {e.detail?.title && <span className="ml-1 text-slate-600 truncate"> · {String(e.detail.title).slice(0, 40)}</span>}
                  </div>
                  <div className="w-24 text-right text-[10px] text-slate-700">{e.ip_address ?? "—"}</div>
                </div>
              );
            })}
          </div>
        )}
      </div>

      {/* Pagination */}
      <div className="flex items-center gap-2 justify-end text-xs text-slate-500">
        <Button variant="outline" size="sm" className="h-7 text-xs" onClick={() => setPage(p => Math.max(0, p - 1))} disabled={page === 0}>
          ← Prev
        </Button>
        <span>Page {page + 1}</span>
        <Button variant="outline" size="sm" className="h-7 text-xs" onClick={() => setPage(p => p + 1)} disabled={entries.length < PAGE_SIZE}>
          Next →
        </Button>
      </div>
    </div>
  );
}
